def test_r4_output_files_are_new_files(tmp_path):
    """The outputs are separate new files, not the input file."""
    plain_path = _write_plaintext(tmp_path)
    _, encrypted_file, encrypted_key_file = task_func(plain_path)
    assert os.path.abspath(encrypted_file) != os.path.abspath(plain_path)
    assert os.path.abspath(encrypted_key_file) != os.path.abspath(plain_path)
    assert os.path.abspath(encrypted_file) != os.path.abspath(encrypted_key_file)
    # The original plaintext file is left untouched.
    assert _read(plain_path) == PLAINTEXT

