def test_r7_encrypted_key_file_holds_rsa_ciphertext(tmp_path):
    """The encrypted-key file holds an RSA ciphertext for the returned key.

    An RSA PKCS#1 v1.5 ciphertext is exactly as long as the modulus of the
    public key, so the file content must have that length.
    """
    public_key, _, encrypted_key_file = task_func(_write_plaintext(tmp_path))
    content = _read(encrypted_key_file).strip()
    assert len(content) == rsa.common.byte_size(public_key.n)

