def test_r8_encrypted_file_is_whole_aes_blocks(tmp_path):
    """The encrypted file is AES-CBC ciphertext: a whole number of blocks."""
    _, encrypted_file, _ = task_func(_write_plaintext(tmp_path))
    content = _read(encrypted_file)
    assert len(content) % (algorithms.AES.block_size // 8) == 0
    assert len(content) >= len(PLAINTEXT)

