def test_r10_encrypted_file_is_not_plaintext_for_other_content(tmp_path):
    """A different input file yields a different encrypted file."""
    first = _write_plaintext(tmp_path, b"first payload\n", "a.txt")
    second = _write_plaintext(tmp_path, b"second payload\n", "b.txt")
    _, enc_first, _ = task_func(first)
